import heapq
import math

def dijkstra(graph, source):
    # graph[u] contains (destination, nonnegative weight)
    if not 0 <= source < len(graph): raise ValueError("Invalid source")
    for edges in graph:
        for v, w in edges:
            if not 0 <= v < len(graph) or not math.isfinite(w) or w < 0:
                raise ValueError("Invalid edge")
    distance = [math.inf] * len(graph)
    parent = [None] * len(graph)
    distance[source] = 0
    queue = [(0, source)]
    while queue:
        du, u = heapq.heappop(queue)
        if du != distance[u]: continue
        for v, w in graph[u]:
            candidate = du + w
            if candidate < distance[v]:
                distance[v] = candidate
                parent[v] = u
                heapq.heappush(queue, (candidate, v))
    return distance, parent

