class MinHeap {
  constructor() { this.data=[]; }
  push(entry) {
    const a=this.data; a.push(entry); let i=a.length-1;
    while(i>0) { const p=Math.floor((i-1)/2); if(a[p][0]<=a[i][0])break;
      [a[p],a[i]]=[a[i],a[p]]; i=p; }
  }
  pop() {
    const a=this.data, first=a[0], last=a.pop();
    if(a.length) { a[0]=last; let i=0;
      while(true) { let c=2*i+1; if(c>=a.length)break;
        if(c+1<a.length&&a[c+1][0]<a[c][0])c++;
        if(a[i][0]<=a[c][0])break; [a[i],a[c]]=[a[c],a[i]]; i=c; }
    }
    return first;
  }
}
function dijkstra(graph, source) {
  if(!Number.isInteger(source)||source<0||source>=graph.length)throw Error('Invalid source');
