#include <iostream>
#include <vector>
#include <queue>
#include <limits>
#include <functional>
#include <stdexcept>
using Edge=std::pair<int,long long>;
std::pair<std::vector<long long>,std::vector<int>> dijkstra(const std::vector<std::vector<Edge>>& g,int source){
 const long long INF=std::numeric_limits<long long>::max();
 if(source<0||source>=(int)g.size())throw std::invalid_argument("source");
 for(const auto& es:g)for(auto [v,w]:es)if(v<0||v>=(int)g.size()||w<0)throw std::invalid_argument("edge");
 std::vector<long long>d(g.size(),INF);std::vector<int>p(g.size(),-1);
 using State=std::pair<long long,int>;
 std::priority_queue<State,std::vector<State>,std::greater<State>>q;
 d[source]=0;q.push({0,source});
 while(!q.empty()){
   auto [du,u]=q.top();q.pop();if(du!=d[u])continue;
   for(auto [v,w]:g[u]){
     if(w>=INF-du)throw std::overflow_error("path exceeds representable distance");
     long long candidate=du+w;
     if(candidate<d[v]){d[v]=candidate;p[v]=u;q.push({candidate,v});}
   }
 }
 return {d,p};
}
int main(){std::vector<std::vector<Edge>>g={{{1,4},{2,1}},{{3,1}},{{1,2},{3,5}},{}};for(auto d:dijkstra(g,0).first)std::cout<<d<<" ";}

