import java.util.*;
class Main {
  static long[] dijkstra(List<List<long[]>> graph,int source){
    if(source<0||source>=graph.size())throw new IllegalArgumentException("source");
    for(var edges:graph)for(var e:edges)if(e[0]<0||e[0]>=graph.size()||e[1]<0)throw new IllegalArgumentException("edge");
    long[] distance=new long[graph.size()];Arrays.fill(distance,Long.MAX_VALUE);
    PriorityQueue<long[]> queue=new PriorityQueue<>(Comparator.comparingLong(a->a[0]));
    distance[source]=0;queue.add(new long[]{0,source});
    while(!queue.isEmpty()){
      long[] state=queue.remove();long du=state[0];int u=(int)state[1];
      if(du!=distance[u])continue;
      for(long[] edge:graph.get(u)){
        int v=(int)edge[0];long w=edge[1];
        if(w>=Long.MAX_VALUE-du)throw new ArithmeticException("path overflow");
        long candidate=du+w;
        if(candidate<distance[v]){distance[v]=candidate;queue.add(new long[]{candidate,v});}
      }
    }
    return distance;
  }
  public static void main(String[] args){
    List<List<long[]>> g=new ArrayList<>();for(int i=0;i<4;i++)g.add(new ArrayList<>());
    g.get(0).add(new long[]{1,4});g.get(0).add(new long[]{2,1});g.get(2).add(new long[]{1,2});g.get(1).add(new long[]{3,1});g.get(2).add(new long[]{3,5});
    System.out.println(Arrays.toString(dijkstra(g,0)));
  }
}
